import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; import java.util.Arrays; import java.util.Collections; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int k = Integer.parseInt(st.nextToken()); int[] a = new int[n]; int[] b = new int[n]; StringTokenizer stA = new StringTokenizer(br.readLine()); StringTokenizer stB = new StringTokenizer(br.readLine()); long currentSum = 0; Integer[] gains = new Integer[n]; for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(stA.nextToken()); b[i] = Integer.parseInt(stB.nextToken()); currentSum += a[i]; gains[i] = Math.max(0, b[i] - a[i]); } Arrays.sort(gains, Collections.reverseOrder()); for (int i = 0; i < k && i < n; i++) { currentSum += gains[i]; } System.out.println(currentSum); } } }